<?php

declare(strict_types=1);
require dirname(__DIR__).'/config/bootstrap.php';
use App\Auth;use App\Database;
$userId=Auth::requireLogin();$stmt=Database::connection()->prepare('SELECT o.*,s.name service FROM orders o JOIN services s ON s.id=o.service_id WHERE o.user_id=:id ORDER BY o.id DESC LIMIT 100');$stmt->execute([':id'=>$userId]);$orders=$stmt->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Orders | SMM Panel</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="/dashboard.php">SMM Panel</a><a class="btn btn-primary btn-sm" href="/order.php">New Order</a></div></nav><main class="container py-4"><h2>My Orders</h2><div class="row g-3"><?php foreach($orders as $o):?><div class="col-12"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><h5 class="mb-0">#<?= (int)$o['id']?> — <?=htmlspecialchars($o['service'])?></h5><span class="badge text-bg-secondary"><?=htmlspecialchars($o['status'])?></span></div><div class="row mt-3"><div class="col-md-3"><small class="text-muted">Quantity</small><div><?=number_format((int)$o['quantity'])?></div></div><div class="col-md-3"><small class="text-muted">Start count</small><div><?=htmlspecialchars((string)($o['start_count']??'-'))?></div></div><div class="col-md-3"><small class="text-muted">Remaining</small><div><?=htmlspecialchars((string)($o['remains']??'-'))?></div></div><div class="col-md-3"><small class="text-muted">Refill</small><div><?=htmlspecialchars((string)($o['refill_status']??($o['refill_id']?'Requested':'-')))?></div></div></div><hr><div><small class="text-muted">Target link</small><div class="text-truncate"><?=htmlspecialchars($o['link'])?></div></div><div class="mt-2 small text-muted">Provider order: <?=htmlspecialchars((string)($o['provider_order_id']??'Pending'))?> · ₦<?=number_format((float)$o['charge'],2)?> · <?=htmlspecialchars($o['created_at'])?></div></div></div></div><?php endforeach;?></div></main></body></html>
